    private ResponseEntity<String> executeRequest(String url, String apiName, Map<String, String> pathParams, Map<String, String> queryParams) {
        try {
            // Build URL with path parameters
            String fullUrl = url;
            if (pathParams != null) {
                for (Map.Entry<String, String> entry : pathParams.entrySet()) {
                    fullUrl = fullUrl.replace("{" + entry.getKey() + "}", entry.getValue());
                }
            }

            // Build URL with query parameters
            UriComponentsBuilder builder = UriComponentsBuilder.fromHttpUrl(fullUrl);
            if (queryParams != null) {
                queryParams.forEach(builder::queryParam);
            }

            // Create request with appropriate headers
            HttpHeaders headers = new HttpHeaders();
            headers.setContentType(MediaType.APPLICATION_JSON);

            // Add API key to headers or query params based on API
            switch (apiName) {
                case "GIPHY":
                    if (apiConfig.getGiphyKey() == null || apiConfig.getGiphyKey().equals("DEMO_KEY")) {
                        throw new HttpClientErrorException(HttpStatus.UNAUTHORIZED, 
                            "Giphy API key not configured. Please set GIPHY_API_KEY environment variable.");
                    }
                    builder.queryParam("api_key", apiConfig.getGiphyKey());
                    break;
                case "GITHUB":
                    if (apiConfig.getGithubKey() == null || apiConfig.getGithubKey().equals("DEMO_KEY")) {
                        throw new HttpClientErrorException(HttpStatus.UNAUTHORIZED, 
                            "GitHub API key not configured. Please set GITHUB_API_KEY environment variable.");
                    }
                    headers.setBearerAuth(apiConfig.getGithubKey());
                    break;
                case "REDDIT":
                    if (apiConfig.getRedditKey() == null || apiConfig.getRedditKey().equals("DEMO_KEY")) {
                        throw new HttpClientErrorException(HttpStatus.UNAUTHORIZED, 
                            "Reddit API key not configured. Please set REDDIT_API_KEY environment variable.");
                    }
                    headers.setBearerAuth(apiConfig.getRedditKey());
                    headers.set("User-Agent", "spring-boot-api-demo/1.0.0 (by /u/apidemo)");
                    break;
                case "NASA":
                    if (apiConfig.getNasaKey() == null || apiConfig.getNasaKey().equals("DEMO_KEY")) {
                        throw new HttpClientErrorException(HttpStatus.TOO_MANY_REQUESTS, 
                            "NASA API key not configured or rate limit exceeded. Please set NASA_API_KEY environment variable.");
                    }
                    // NASA API key is added as query parameter
                    break;
                case "HACKERNEWS":
                    // HackerNews doesn't require API key
                    break;
            }

            // Make the request
            HttpEntity<String> entity = new HttpEntity<>(headers);
            ResponseEntity<String> response = restTemplate.exchange(
                builder.toUriString(),
                HttpMethod.GET,
                entity,
                String.class
            );

            // Handle rate limits
            if (response.getStatusCode() == HttpStatus.TOO_MANY_REQUESTS) {
                throw new HttpClientErrorException(HttpStatus.TOO_MANY_REQUESTS, 
                    "Rate limit exceeded. Please try again later.");
            }

            return response;

        } catch (HttpClientErrorException e) {
            if (e.getStatusCode() == HttpStatus.TOO_MANY_REQUESTS) {
                return ResponseEntity.status(HttpStatus.TOO_MANY_REQUESTS)
                    .body("Rate limit exceeded. Please try again later.");
            }
            return ResponseEntity.status(e.getStatusCode())
                .body(e.getResponseBodyAsString());
        } catch (HttpServerErrorException e) {
            return ResponseEntity.status(e.getStatusCode())
                .body(e.getResponseBodyAsString());
        } catch (Exception e) {
            return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR)
                .body("An error occurred: " + e.getMessage());
        }
    }

    private ResponseEntity<String> simulateRandomError() {
        int errorCode = random.nextInt(3);
        switch (errorCode) {
            case 0:
                throw new HttpClientErrorException(HttpStatus.BAD_REQUEST, "Simulated bad request error");
            case 1:
                throw new HttpClientErrorException(HttpStatus.UNAUTHORIZED, "Simulated unauthorized error");
            default:
                throw new HttpServerErrorException(HttpStatus.INTERNAL_SERVER_ERROR, "Simulated server error");
        }
    }
}

package com.example.apidemo.config;

import io.opentelemetry.api.trace.Span;
import io.opentelemetry.api.trace.StatusCode;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.http.HttpRequest;
import org.springframework.http.client.ClientHttpRequestExecution;
import org.springframework.http.client.ClientHttpRequestInterceptor;
import org.springframework.http.client.ClientHttpResponse;
import org.springframework.web.client.RestTemplate;
import org.springframework.web.client.HttpClientErrorException;
import org.springframework.web.client.HttpServerErrorException;
import org.springframework.web.client.ResourceAccessException;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.net.ConnectException;
import java.net.SocketTimeoutException;
import java.net.UnknownHostException;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;

@Configuration
public class RestTemplateConfig {

    @Bean
    public RestTemplate restTemplate() {
        RestTemplate restTemplate = new RestTemplate();
        List<ClientHttpRequestInterceptor> interceptors = new ArrayList<>();
        interceptors.add(new OpenTelemetryClientHttpRequestInterceptor());
        restTemplate.setInterceptors(interceptors);
        return restTemplate;
    }

    private static class OpenTelemetryClientHttpRequestInterceptor implements ClientHttpRequestInterceptor {
        @Override
        public ClientHttpResponse intercept(HttpRequest request, byte[] body, ClientHttpRequestExecution execution) throws IOException {
            Span span = Span.current();
            if (span != null) {
                span.setAttribute("http.request.method", request.getMethod().name());
                span.setAttribute("http.url", request.getURI().toString());
                span.setAttribute("url.full", request.getURI().toString());
                span.setAttribute("server.address", request.getURI().getHost());
                span.setAttribute("net.peer.name", request.getURI().getHost());
                span.setAttribute("http.request.headers", request.getHeaders().toString());
                if (body != null && body.length > 0) {
                    span.setAttribute("http.request.body", new String(body, StandardCharsets.UTF_8));
                }
            }

            try {
                ClientHttpResponse response = execution.execute(request, body);
                if (span != null) {
                    int statusCode = response.getStatusCode().value();
                    String statusText = response.getStatusText();

                    span.setAttribute("http.response.status_code", String.valueOf(statusCode));
                    span.setAttribute("http.response.status_text", statusText);
                    span.setAttribute("http.response.headers", response.getHeaders().toString());

                    if (statusCode >= 400) {
                        // Read response body for error details
                        String responseBody = "";
                        try (BufferedReader reader = new BufferedReader(new InputStreamReader(response.getBody(), StandardCharsets.UTF_8))) {
                            responseBody = reader.lines().collect(Collectors.joining("\n"));
                        }

                        String errorMessage;
                        if (statusCode >= 500) {
                            errorMessage = String.format("Server Error: HTTP %d %s - %s", statusCode, statusText, responseBody);
                        } else if (statusCode == 429) {
                            errorMessage = String.format("Rate Limited: HTTP %d %s - %s", statusCode, statusText, responseBody);
                        } else if (statusCode == 403) {
                            errorMessage = String.format("Forbidden: HTTP %d %s - %s", statusCode, statusText, responseBody);
                        } else if (statusCode == 401) {
                            errorMessage = String.format("Unauthorized: HTTP %d %s - %s", statusCode, statusText, responseBody);
                        } else {
                            errorMessage = String.format("Client Error: HTTP %d %s - %s", statusCode, statusText, responseBody);
                        }

                        span.setStatus(StatusCode.ERROR, errorMessage);
                        span.setAttribute("error.type", String.valueOf(statusCode));
                        span.setAttribute("error.message", responseBody);
                        span.recordException(new RuntimeException(errorMessage));
                    } else {
                        String successMessage = String.format("HTTP %d %s", statusCode, statusText);
                        span.setStatus(StatusCode.OK, successMessage);
                    }
                }
                return response;
            } catch (HttpClientErrorException e) {
                if (span != null) {
                    String errorMessage = String.format("Client Error: HTTP %d %s - %s", 
                        e.getStatusCode().value(), e.getStatusText(), e.getResponseBodyAsString());
                    RuntimeException error = new RuntimeException(errorMessage);
                    span.recordException(error);
                    span.setStatus(StatusCode.ERROR, error.getMessage());
                    span.setAttribute("error.type", "HTTP_CLIENT_ERROR");
                    span.setAttribute("error.message", e.getResponseBodyAsString());
                }
                throw e;
            } catch (HttpServerErrorException e) {
                if (span != null) {
                    String errorMessage = String.format("Server Error: HTTP %d %s - %s", 
                        e.getStatusCode().value(), e.getStatusText(), e.getResponseBodyAsString());
                    RuntimeException error = new RuntimeException(errorMessage);
                    span.recordException(error);
                    span.setStatus(StatusCode.ERROR, error.getMessage());
                    span.setAttribute("error.type", "HTTP_SERVER_ERROR");
                    span.setAttribute("error.message", e.getResponseBodyAsString());
                }
                throw e;
            } catch (ResourceAccessException e) {
                if (span != null) {
                    String errorMessage;
                    if (e.getCause() instanceof SocketTimeoutException) {
                        errorMessage = "Request Timeout: " + e.getMessage();
                        span.setAttribute("error.type", "TIMEOUT");
                    } else if (e.getCause() instanceof ConnectException) {
                        errorMessage = "Connection Failed: " + e.getMessage();
                        span.setAttribute("error.type", "CONNECTION_FAILED");
                    } else if (e.getCause() instanceof UnknownHostException) {
                        errorMessage = "Unknown Host: " + e.getMessage();
                        span.setAttribute("error.type", "UNKNOWN_HOST");
                    } else {
                        errorMessage = "Resource Access Error: " + e.getMessage();
                        span.setAttribute("error.type", "RESOURCE_ACCESS_ERROR");
                    }
                    RuntimeException error = new RuntimeException(errorMessage);
                    span.recordException(error);
                    span.setStatus(StatusCode.ERROR, error.getMessage());
                    span.setAttribute("error.message", e.getMessage());
                }
                throw e;
            } catch (IOException e) {
                if (span != null) {
                    String errorMessage = "IO Error: " + e.getMessage();
                    RuntimeException error = new RuntimeException(errorMessage);
                    span.recordException(error);
                    span.setStatus(StatusCode.ERROR, error.getMessage());
                    span.setAttribute("error.type", "IO_EXCEPTION");
                    span.setAttribute("error.message", e.getMessage());
                }
                throw e;
            }
        }
    }
}

package com.example.apidemo.model;

import org.springframework.http.ResponseEntity;

public class ApiResponse {
    private int statusCode;
    private String body;
    private String error;

    public ApiResponse(int statusCode, String body, String error) {
        this.statusCode = statusCode;
        this.body = body;
        this.error = error;
    }

    public int getStatusCode() {
        return statusCode;
    }

    public String getBody() {
        return body;
    }

    public String getError() {
        return error;
    }

    public ResponseEntity<String> getResponse() {
        if (error != null) {
            return ResponseEntity.status(statusCode).body(error);
        }
        return ResponseEntity.status(statusCode).body(body);
    }
}

package com.example.apidemo.filter;

import io.opentelemetry.api.trace.Span;
import io.opentelemetry.api.trace.SpanKind;
import io.opentelemetry.api.trace.StatusCode;
import jakarta.servlet.FilterChain;
import jakarta.servlet.ServletException;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import org.springframework.stereotype.Component;
import org.springframework.web.filter.OncePerRequestFilter;

import java.io.IOException;

@Component
public class OpenTelemetryFilter extends OncePerRequestFilter {

    @Override
    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response, FilterChain filterChain)
            throws ServletException, IOException {
        Span span = Span.current();
        if (span != null) {
            try {
                filterChain.doFilter(request, response);

                int statusCode = response.getStatus();
                if (statusCode >= 400) {
                    String errorMessage = String.format("HTTP %d", statusCode);
                    span.setStatus(StatusCode.ERROR, errorMessage);
                } else {
                    span.setStatus(StatusCode.OK);
                }
            } catch (Exception e) {
                span.setStatus(StatusCode.ERROR, e.getMessage());
                throw e;
            }
        } else {
            filterChain.doFilter(request, response);
        }
    }
}

